        <div class="stmb-topical-clip">
            <div class="world_entry_form_control">
                <h4>${x(L("STMemoryBooks_TopicalClip_SourceMemoryBook","Source Memory Book"))}</h4>
                <select id="stmb-topical-clip-lorebook-select" class="text_pole">
                    ${Q}
                </select>
            </div>
            <label class="world_entry_form_control">
                <h4>${x(L("STMemoryBooks_TopicalClip_Topic","Topic"))}</h4>
                <input id="stmb-topical-clip-topic" class="text_pole" type="text" />
            </label>
            <label class="world_entry_form_control">
                <h4>${x(L("STMemoryBooks_TopicalClip_Keywords","Keywords"))}</h4>
                <input id="stmb-topical-clip-keywords" class="text_pole" type="text" />
                <small class="opacity70p">${x(L("STMemoryBooks_TopicalClip_KeywordsHelp","Saving updates this entry’s activation keywords. Empty keywords are filled from Topic."))}</small>
            </label>
            <label class="world_entry_form_control">
                <h4>${x(L("STMemoryBooks_TopicalClip_Mode","Mode"))}</h4>
                <select id="stmb-topical-clip-mode" class="text_pole">
                    <option value="create" selected>${x(L("STMemoryBooks_TopicalClip_CreateNew","Create new Topical Clip"))}</option>
                    <option value="update">${x(L("STMemoryBooks_TopicalClip_UpdateExisting","Update existing entry"))}</option>
                </select>
            </label>
            <div id="stmb-topical-clip-target-row" class="world_entry_form_control" hidden>
                <h4>${x(L("STMemoryBooks_TopicalClip_TargetEntry","Entry to update"))}</h4>
                <label class="checkbox_label"><input id="stmb-topical-clip-show-disabled" type="checkbox" /> <span>${x(L("STMemoryBooks_Clip_ShowDisabled","Show disabled clips"))}</span></label>
                <select id="stmb-topical-clip-target-select" class="text_pole"></select>
                <small id="stmb-topical-clip-metadata-message" class="opacity70p"></small>
                <small class="opacity70p">${x(L("STMemoryBooks_TopicalClip_DisabledTargetHelp","Updating a disabled clip enables it when saved."))}</small>
            </div>
            <div id="stmb-topical-clip-rebuild-row" class="world_entry_form_control" hidden>
                <label class="checkbox_label">
                    <input id="stmb-topical-clip-rebuild-all" type="checkbox" />
                    <span>${x(L("STMemoryBooks_TopicalClip_RebuildAll","Rebuild from all source memories"))}</span>
                </label>
            </div>
            <div class="world_entry_form_control">
                <h4>${x(L("STMemoryBooks_TopicalClip_SourceTypes","Sources"))}</h4>
                <label class="checkbox_label">
                    <input id="stmb-topical-clip-include-memories" type="checkbox" checked />
                    <span>${x(L("STMemoryBooks_TopicalClip_IncludeMemories","Include saved Memories"))}</span>
                </label>
                <label class="checkbox_label">
                    <input id="stmb-topical-clip-include-messages" type="checkbox" />
                    <span>${x(L("STMemoryBooks_TopicalClip_IncludeMessages","Include chat messages"))}</span>
                </label>
                <label class="checkbox_label">
                    <input id="stmb-topical-clip-include-hidden-messages" type="checkbox"${s1().topicalClipIncludeHiddenMessages?" checked":""} />
                    <span>${x(L("STMemoryBooks_TopicalClip_IncludeHiddenMessages","Also use hidden messages"))}</span>
                </label>
                <button id="stmb-topical-clip-extract" type="button" class="menu_button">${x(L("STMemoryBooks_Extract_Open","Extract…"))}</button>
                <select id="stmb-topical-clip-message-mode" class="text_pole" hidden>
                    <option value="range">${x(L("STMemoryBooks_TopicalClip_MessageRange","Message range"))}</option>
                    <option value="selection">${x(L("STMemoryBooks_Extract_Selected","Selected messages"))}</option>
                </select>
                <div id="stmb-topical-clip-selection-info" hidden>
                    <span id="stmb-topical-clip-selection-count"></span>
                    <button id="stmb-topical-clip-edit-selection" type="button" class="menu_button">${x(L("STMemoryBooks_Extract_Edit","Edit selection"))}</button>
                </div>
                <div id="stmb-topical-clip-message-range" class="flex-container gap10px" hidden>
                    <label class="flex1"><span>${x(L("STMemoryBooks_TopicalClip_MessageStart","Start message ID"))}</span><input id="stmb-topical-clip-message-start" class="text_pole" type="number" min="0" /></label>
                    <label class="flex1"><span>${x(L("STMemoryBooks_TopicalClip_MessageEnd","End message ID"))}</span><input id="stmb-topical-clip-message-end" class="text_pole" type="number" min="0" /></label>
                </div>
            </div>
            <div id="stmb-topical-clip-source-picker-row" class="world_entry_form_control">
                <label class="checkbox_label">
                    <input id="stmb-topical-clip-use-selected-sources" type="checkbox" />
                    <span>${x(L("STMemoryBooks_TopicalClip_UseSelectedMemories","Use only selected memories"))}</span>
                </label>
                <div id="stmb-topical-clip-source-picker-controls" hidden>
                    <h4>${x(L("STMemoryBooks_TopicalClip_SourceMemoryPicker","Source memories"))}</h4>
                    <div class="stmb-button-row marginBot5">
                        <button id="stmb-topical-clip-source-select-all" type="button" class="menu_button stmb-nowrap-button">${x(L("STMemoryBooks_SelectAll","Select All"))}</button>
                        <button id="stmb-topical-clip-source-deselect-all" type="button" class="menu_button stmb-nowrap-button">${x(L("STMemoryBooks_DeselectAll","Deselect All"))}</button>
                    </div>
                    <div id="stmb-topical-clip-source-list" style="max-height:300px; overflow-y:auto; border:1px solid var(--SmartHover2); padding:6px"></div>
                </div>
            </div>
            ${X7("stmb-topical-clip-profile-select",{label:L("STMemoryBooks_TopicalClip_Profile","Generation Profile")})}
            ${gH("stmb-topical-clip")}
            <div class="buttons_block justifyCenter gap10px whitespacenowrap">
                <button id="stmb-topical-clip-edit-prompt" type="button" class="menu_button">${x(L("STMemoryBooks_TopicalClip_EditPrompt","Edit Topical Clip Prompt"))}</button>
                <button id="stmb-topical-clip-edit-format" type="button" class="menu_button">${x(L("STMemoryBooks_TopicalClip_EditFormat","Edit Topical Format"))}</button>
                <button id="stmb-combine-clips-open" type="button" class="menu_button">${x(L("STMemoryBooks_CombineClips_Open","Combine Clips"))}</button>
            </div>
            <div id="stmb-topical-clip-diagnostics" class="info_block info-block"></div>
            <div class="buttons_block justifyCenter gap10px whitespacenowrap">
                <button id="stmb-topical-clip-generate" type="button" class="menu_button whitespacenowrap">${x(L("STMemoryBooks_TopicalClip_GenerateDraft","Generate Draft"))}</button>
            </div>
            <label class="world_entry_form_control">
                <h4>${x(L("STMemoryBooks_TopicalClip_Draft","Generated draft"))}</h4>
                <textarea id="stmb-topical-clip-draft" class="text_pole stmb-clip-preview" rows="14"></textarea>
            </label>
            <div class="buttons_block justifyCenter gap10px whitespacenowrap">
                <button id="stmb-topical-clip-save" type="button" class="menu_button whitespacenowrap" disabled>${x(L("STMemoryBooks_TopicalClip_Save","Save Topical Clip"))}</button>
            </div>
        </div>
